questionvariables.text:
/*choosing random numbers that give equal sum*/
is_sum: rand(7) + 5; 
/*is_sum: 6;*/ 
list_num: []; 
sum_nums: 0;  
while sum_nums # is_sum do (    
    list_num: makelist((rand(4) + 1), i, 1, 3),     
    sum_nums: sum(list_num[i], i, 1, 3) );  
list_num;

/*items in the bags*/
ball_I_white:list_num[1];
ball_I_red:list_num[2];
ball_I_black:list_num[3];
/*phase 2*/
ball_2_white:list_num[2];
ball_2_red:list_num[3];
ball_2_black:list_num[1];
/*phase 3*/
ball_3_white:list_num[3];
ball_3_red:list_num[1];
ball_3_black:list_num[2];
/*worked solution variables*/
sum_combination:binomial(is_sum, 2);
p_a_b1:(binomial(ball_I_white,1)*binomial(ball_I_black,1))/sum_combination;
p_a_b2:(binomial(ball_2_white,1)*binomial(ball_2_black,1))/sum_combination;
p_a_b3:(binomial(ball_3_white,1)*binomial(ball_3_black,1))/sum_combination;

s1:((1/3)*p_a_b2);
s2:(((1/3)*p_a_b1)+((1/3)*p_a_b2)+((1/3)*p_a_b3));
p_b2_a:s1/s2;
sol1:decimalplaces(p_b2_a,2);
